def solve(path: str) -> str:
    """Simplify an absolute Unix-style path.
    Resolve '.' (current directory) and '..' (parent directory), collapse multiple slashes,
    and ensure no trailing slash unless the result is the root '/'.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

def solve(tokens):
    """Evaluate Reverse Polish notation expression given as list of string tokens.
    Supports +, -, *, / where division truncates toward zero.
    Returns integer result.
    """
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                res = int(a / b)
                stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

