    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Returns the integer result, where division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Truncate toward zero like int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0]

