def solve(path):
    """Simplify an absolute Unix path.
    Implements the classic stack algorithm handling '.', '..' and redundant slashes.
    The result never ends with a trailing slash, except for the root '/'.
    """
    if not isinstance(path, str) or not path.startswith('/'):
        # According to spec input should be an absolute path; treat invalid as root.
        return '/'
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty we stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    # Ensure no trailing slash (except root)
    if len(simplified) > 1 and simplified.endswith('/'):
        simplified = simplified.rstrip('/')
    return simplified

def solve(path: str) -> str:
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

