def solve(grid):
    """Return the number of islands in a binary grid.
    An island is a group of adjacent (up/down/left/right) cells with value 1.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=cols:
                continue
            if visited[i][j] or grid[i][j]==0:
                continue
            visited[i][j] = True
            # push neighbors
            stack.append((i-1,j))
            stack.append((i+1,j))
            stack.append((i,j-1))
            stack.append((i,j+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                count += 1
                dfs(i,j)
    return count

