    """Parse a CSV line according to simplified rules.
    - Fields are separated by commas.
    - Fields may be quoted with double quotes.
    - Inside quoted fields, commas are literal and double double-quotes represent a single quote.
    - An empty line yields a list with a single empty string.
    """
    if line == "":
        return [""]
    fields = []
