def solve(weights, values, capacity):
    """0/1 knapsack: maximum total value with total weight <= capacity.
    Uses DP with O(capacity) memory.
    """
    # Ensure inputs are list-like
    if not weights or capacity <= 0:
        return 0
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w > capacity:
            continue
        # iterate backwards to avoid reuse of same item
        for cap in range(capacity, w - 1, -1):
            new_val = dp[cap - w] + v
            if new_val > dp[cap]:
                dp[cap] = new_val
    return dp[capacity]

