def solve(n, b):
    """Convert integer n to base b (2-36) string.
    Handles negative numbers with leading '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

