def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount`.
    `coins` is a list of positive integers. Unlimited supply of each coin.
    If it is impossible, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible answer.
    INF = amount + 1  # more than max possible coins (using 1-value coins)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive coins
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

