def solve(a, b):
    """Levenshtein distance for any sequence inputs.
    If inputs are strings they are treated as sequences of characters. For other
    iterables (lists, tuples, bytes, etc.) the elements are compared directly.
    Uses O(min(m,n)) space DP.
    """
    # Convert to list-like sequences for uniform handling
    def to_seq(x):
        if isinstance(x, str):
            return list(x)
        try:
            # strings are also iterable, but handled above
            return list(x)
        except TypeError:
            # Non‑iterable: treat as single element string representation
            return [x]
    seq_a = to_seq(a)
    seq_b = to_seq(b)
    m, n = len(seq_a), len(seq_b)
    if m == 0:
        return n
    if n == 0:
        return m
    # Ensure n <= m to use less space
    if n > m:
        seq_a, seq_b = seq_b, seq_a
        m, n = n, m
    prev = list(range(n + 1))  # distance for empty prefix of seq_a
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        ai = seq_a[i - 1]
        for j in range(1, n + 1):
            cost = 0 if ai == seq_b[j - 1] else 1
            cur[j] = min(prev[j] + 1,      # deletion
                         cur[j - 1] + 1,   # insertion
                         prev[j - 1] + cost)  # substitution
        prev = cur
    return prev[n]

def solve(line: str):
    """Parse a single CSV line into a list of fields.
    Handles quoted fields, escaped quotes ("" -> ") and commas inside quotes.
    Empty line returns [''].
    """
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quotes = False
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                # start of quoted field
                in_quotes = True
            else:
                cur.append(ch)
        i += 1
    # Append last field
    fields.append(''.join(cur))
    # If line is empty, fields will be [''] as desired
    return fields

