def solve(line: str):
    """Parse a single CSV line into a list of fields.
    Fields may be quoted with double quotes. Inside quoted fields,
    commas are treated as literal characters, and a pair of double quotes
    represents a single quote character.
    """
    fields = []
    i = 0
    n = len(line)
    # Special case: empty line should return ['']
    if n == 0:
        return ['']
    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        i += 1  # skip closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            fields.append(''.join(field_chars))
            # After quoted field, expect comma or end of line
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    return fields

